// Verify the X-LegalAI-Signature header (HMAC-SHA256 of the raw body) and
// turn the event into a Slack message. Unsigned or tampered events are dropped.
const crypto = require('crypto');
const secret = $env.LEGAL_AI_WEBHOOK_SECRET || '';
const item = $input.first();
const raw = item.binary && item.binary.data
  ? await this.helpers.getBinaryDataBuffer(0, 'data')
  : Buffer.from(JSON.stringify(item.json.body || {}));
const headers = item.json.headers || {};
const signature = headers['x-legalai-signature'] || '';

if (secret) {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
  const ok = signature.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
  if (!ok) {
    return [];
  }
}

const event = JSON.parse(raw.toString('utf8'));
const d = event.details || {};
const who = event.actor || 'someone';
const messages = {
  'document.indexed': `:page_facing_up: *${d.title || d.filename}* indexed by ${who} (${d.chunks} passages, ${d.category}, via ${d.channel})`,
  'document.ingest_failed': `:warning: Could not index *${d.filename}* (via ${d.channel}): ${d.error}`,
  'document.deleted': `:wastebasket: *${d.filename}* deleted by ${who}`,
  'security.login_failed': `:closed_lock_with_key: Failed sign-in for *${who}* from ${event.ip}`,
  'security.login_denied': `:no_entry: Sign-in attempt on disabled account *${who}* from ${event.ip}`,
  'security.login_locked': `:lock: Sign-in for *${who}* from ${event.ip} blocked after repeated failures`,
  'security.ip_denied': `:no_entry_sign: Request from non-allowed address ${event.ip} to ${event.resource}`,
  'security.audit_tamper_detected': `:rotating_light: Audit log integrity check FAILED at event #${d.first_invalid_id}`,
  'user.created': `:bust_in_silhouette: ${who} added user *${event.resource}* (${d.role})`,
  'user.updated': `:pencil2: ${who} updated user *${event.resource}*`,
  'user.password_reset': `:key: ${who} reset the password for *${event.resource}*`,
  'integration.test': `:white_check_mark: n8n received a test event from Local Legal AI (sent by ${who})`,
};
const text = messages[event.event] || `${event.event}: ${event.resource || ''}`;
return [{ json: { event: event.event, severity: event.event.startsWith('security.') ? 'high' : 'info', text } }];
